{
  "name": "opencode-fff-search",
  "version": "0.8.0",
  "description": "Plugin that replaces default grep/glob with fff's ultra-fast search (OpenCode + MiMo Code)",
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": "./index.js"
  },
  "files": [
    "index.js",
    "constants.js",
    "helpers.js",
    "filters.js",
    "gitignore.js",
    "search.js"
  ],
  "keywords": [
    "opencode",
    "plugin",
    "fff",
    "search",
    "file-search",
    "grep",
    "glob",
    "fast",
    "fuzzy",
    "frecency"
  ],
  "author": "ozgurulukir",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ozgurulukir/opencode-fff-search.git"
  },
  "bugs": {
    "url": "https://github.com/ozgurulukir/opencode-fff-search/issues"
  },
  "homepage": "https://github.com/ozgurulukir/opencode-fff-search#readme",
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.14.28",
    "@mimo-ai/plugin": "^0.1.0-preview.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": { "optional": true },
    "@mimo-ai/plugin": { "optional": true }
  },
  "dependencies": {
    "@ff-labs/fff-bun": "^0.8.4",
    "@ff-labs/fff-node": "^0.8.1",
    "minimatch": "^10.2.5"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "os": [
    "darwin",
    "linux",
    "win32"
  ],
  "cpu": [
    "x64",
    "arm64"
  ]
}
